function service(type) {
  const data = servicePages[type];
  const isRental = type === 'rental';
  return `${breadcrumbs([{ name: data.eyebrow, path: paths[type] }])}<section class="section page-hero"><div class="container page-hero-grid"><div>${tag(isRental ? 'NA WYDARZENIE, PROJEKT LUB SEZON' : 'INDYWIDUALNA OFERTA ZAKUPU')}<h1>${isRental ? 'Wynajem' : 'Sprzedaż'}<br>klimatyzacji<br><span>przemysłowej.</span></h1><p class="lead">${e(data.intro)}</p><div class="page-actions">${quoteButton(isRental ? 'Zapytaj o wynajem' : 'Zapytaj o zakup', type)}<a class="secondary-phone" href="tel:${company.phone}">${phoneIcon}${e(company.phoneDisplay)}</a></div></div><div>${photoFigure(isRental ? 'installation' : 'hero', isRental ? 'Klimatyzacja REKORD / powietrze doprowadzone do hali' : 'Flota urządzeń REKORD / dobór do potrzeb obiektu', { loading: 'eager', className: 'page-photo', gallery: true })}<div class="photo-under-note"><span>${snowflake}</span><p>${isRental ? 'Sprzęt, kanały powietrzne i dostawę ustalamy w jednej konfiguracji.' : 'Model, stan i wyposażenie urządzenia potwierdzamy przed zakupem.'}</p></div></div></div></section><section class="section section--ice"><div class="container detail-layout"><div>${tag(isRental ? 'JAK ZAPLANOWAĆ WYNAJEM' : 'JAK ZAPLANOWAĆ ZAKUP')}<h2>${isRental ? 'Chłodzenie na czas<br>Twojego projektu.' : 'Sprzęt do Twoich<br>warunków pracy.'}</h2><p>Od pierwszej rozmowy do ustalonego zakresu. Zaczynamy od przestrzeni, którą chcesz schłodzić.</p></div>${detailSections(data.sections)}</div></section>${isRental ? `<section class="section"><div class="container selection-grid"><div>${tag('PRZED WYCENĄ')}<h2>Co przygotować<br>do wynajmu?</h2></div><div><p class="lead-small">Wymiary, izolacja, źródła ciepła, temperatura, zasilanie i termin.</p><a class="text-link" href="/poradniki/wynajem-klimatyzacji-co-przygotowac/">Zobacz checklistę ${arrow}</a></div></div></section>` : ''}${equipmentSection({ service: type })}${processBlock()}${faqBlock(data.faq, isRental ? 'Wynajem.\nCo warto ustalić?' : 'Zakup.\nCo warto ustalić?')}${callout({ service: type })}`;
}

function catalog() {
  return `${breadcrumbs([{ name: 'Klimatyzatory', path: paths.catalog }])}<section class="section catalog-intro"><div class="container"><div class="section-heading"><div>${tag('SPRZĘT DO DUŻYCH PRZESTRZENI')}<h1>Klimatyzatory<br><span>przemysłowe.</span></h1></div><div class="catalog-intro-copy"><p class="lead">Lennox, Carrier i Dantherm. Mobilne jednostki do hal, magazynów i eventów — w ofercie wynajmu oraz do indywidualnego zapytania o zakup.</p><p>Porównaj modele i opisz warunki w obiekcie. Pomożemy ustalić właściwą konfigurację.</p></div></div>${equipmentCards()}<p class="equipment-note">Moce Lennox i Carrier przedstawiamy orientacyjnie. Dokładne oznaczenie, parametry i wyposażenie konkretnej jednostki potwierdzamy w ofercie.</p></div></section><section class="section section--ice"><div class="container selection-grid"><div>${tag('DOBÓR ZACZYNA SIĘ OD WARUNKÓW')}<h2>Same metry<br>to za mało.</h2></div><div><p class="lead-small">Liczą się również wysokość i izolacja, nasłonecznienie, liczba osób, ciepło od urządzeń oraz ruch przy wejściach.</p><p>Podaj oczekiwaną temperaturę i dostępne zasilanie. Omówimy moc, ustawienie jednostek i rozprowadzenie powietrza.</p>${quoteButton('Poproś o dobór klimatyzacji')}</div></div></section>${installationBlock()}${faqBlock(faq.filter(item => /Jakie klimatyzatory|Jak dobieracie|zasilaniem|zakup/.test(item.q)), 'Urządzenia.\nCo warto wiedzieć?')}${callout()}`;
}

function product(item) {
  const productFaq = [
    { q: `Czy ${item.name} można wynająć lub kupić?`, a: 'Przygotowujemy zapytania o wynajem oraz indywidualne oferty zakupu. Podaj lokalizację, planowany termin i zastosowanie. Dostępność, wyposażenie i warunki potwierdzimy dla konkretnego zamówienia.' },
    { q: 'Czy sama moc wystarczy do wyboru urządzenia?', a: 'Do doboru potrzebne są także wymiary i izolacja obiektu, źródła ciepła, liczba osób, ruch przy bramach oraz oczekiwana temperatura. Ustalamy też sposób podania powietrza i możliwości zasilania.' },
    { q: 'Jak uzgodnić transport i konfigurację?', a: 'Przekaż miejsce realizacji, dostęp do rozładunku i plan obiektu. Ustalimy miejsce jednostki, trasę kanałów oraz zakres wyposażenia i dostawy w Polsce lub Unii Europejskiej.' },
  ];
  return `${breadcrumbs([{ name: 'Klimatyzatory', path: paths.catalog }, { name: item.name, path: productPath(item) }])}<section class="section product-hero"><div class="container product-hero-grid"><div class="product-gallery">${photoFigure(item.slug, `${item.name} / zdjęcie urządzenia z oferty REKORD`, { loading: 'eager', gallery: true, sizes: '(max-width: 850px) calc(100vw - 40px), 54vw' })}<a class="gallery-secondary" href="/assets/climate-installation.webp" data-gallery-image="/assets/climate-installation.webp" data-gallery-alt="Przykład instalacji REKORD: klimatyzatory i kanały powietrzne przy hali">${imageMarkup('installation', { sizes: '100px' })}<span>Zobacz sposób doprowadzenia powietrza<small>Przykładowa instalacja REKORD</small></span>${diagonal}</a></div><div class="product-summary">${tag('KLIMATYZATOR PRZEMYSŁOWY')}<h1>${e(item.brand)}<br><span>${e(item.model)}</span></h1><div class="product-power"><strong>${e(item.power)}</strong><span>${item.approximate ? 'orientacyjna moc chłodnicza' : 'nominalna moc chłodnicza'}</span></div><p class="lead-small">${e(item.description)}</p><div class="product-actions">${quoteButton('Zapytaj o wynajem', 'rental', item.slug)}${quoteButton('Zapytaj o zakup', 'sale', item.slug, 'outline')}</div><p class="product-availability">Dostępność i konfigurację potwierdzamy w indywidualnej ofercie.</p></div></div></section><section class="section product-details-section"><div class="container detail-layout"><div>${tag('DANE URZĄDZENIA')}<h2>Parametry<br>i konfiguracja.</h2><p>${e(item.powerNote)}</p><a class="source-link" href="${e(item.sourceUrl)}" target="_blank" rel="noopener noreferrer">Źródło danych urządzenia ${diagonal}<span class="sr-only"> — otwiera się w nowej karcie</span></a></div><dl class="spec-table">${item.specs.map(spec => `<div><dt>${e(spec.label)}</dt><dd>${e(spec.value)}</dd></div>`).join('')}</dl></div></section><section class="section section--ice"><div class="container detail-layout"><div>${tag('ZASTOSOWANIE W PRAKTYCE')}<h2>Sprzęt to część<br>rozwiązania.</h2><p>${e(item.application)}</p></div>${detailSections(item.details)}</div></section>${faqBlock(productFaq, `${item.name}.\nPytania przed wyborem.`)}<section class="section related-equipment"><div class="container"><div class="section-heading"><div>${tag('POZOSTAŁE MOŻLIWOŚCI')}<h2>Porównaj urządzenia.</h2></div><a class="text-link" href="${paths.catalog}">Cały katalog ${arrow}</a></div><div class="related-grid">${equipment.filter(other => other.slug !== item.slug).map(other => `<a class="related-card" href="${productPath(other)}">${imageMarkup(other.slug, { sizes: '(max-width: 700px) 100px, 180px' })}<span><small>${e(other.power)} / ${other.approximate ? 'moc orientacyjna' : 'moc chłodnicza'}</small><strong>${e(other.name)}</strong></span>${diagonal}</a>`).join('')}</div></div></section>${callout({ model: item.slug })}`;
}

function application(item) {
  return `${breadcrumbs([{ name: 'Zastosowania', path: '/#zastosowania' }, { name: item.title, path: applicationPath(item) }])}<section class="section page-hero application-hero"><div class="container page-hero-grid"><div>${tag('KLIMATYZACJA DOPASOWANA DO PRZESTRZENI')}<h1>${e(item.eyebrow)}<span>.</span></h1><p class="lead">${e(item.description)}</p><div class="page-actions">${quoteButton('Dobierz klimatyzację')}<a class="secondary-phone" href="tel:${company.phone}">${phoneIcon}${e(company.phoneDisplay)}</a></div></div>${photoFigure('installation', 'Instalacja REKORD / chłodzenie z rozprowadzeniem powietrza', { loading: 'eager', gallery: true, className: 'page-photo' })}</div></section><section class="section section--ice"><div class="container detail-layout"><div>${tag('ZACZNIJMY OD TWOJEGO OBIEKTU')}<h2>Co uwzględnimy<br>przy doborze?</h2><p>Te informacje pozwolą omówić urządzenia, rozmieszczenie nawiewu i warunki realizacji.</p></div><ul class="checklist checklist--large">${item.details.map(detail => `<li>${e(detail)}</li>`).join('')}</ul></div></section><section class="section"><div class="container detail-layout"><div>${tag(item.title.toUpperCase())}<h2>Warunki na miejscu<br>wyznaczają plan.</h2></div>${detailSections(item.sections ?? [])}</div></section>${equipmentSection({ heading: 'Urządzenia do\nTwojego projektu.' })}${processBlock()}${faqBlock(item.faq ?? faq, 'Zapytaj o swoje\nzastosowanie.')}${callout()}`;
}

